function quitSmoking(cigsPerDay, pricePerPack, yearsSmoked){
  cigsPerDay=Math.max(0,(+cigsPerDay)||0);
  pricePerPack=(+pricePerPack); if(isNaN(pricePerPack))pricePerPack=0;
  yearsSmoked=(+yearsSmoked); if(isNaN(yearsSmoked))yearsSmoked=0;
  if(cigsPerDay<=0) return {error:'请输入每日吸烟支数'};
  var dailyCost=(cigsPerDay/20)*pricePerPack;
  var yearlyCost=dailyCost*365;
  var totalCost=yearlyCost*yearsSmoked;
  var timeYearMin=cigsPerDay*5*365;
  return {dailyCost:Math.round(dailyCost*100)/100, yearlyCost:Math.round(yearlyCost*100)/100,
    totalCost:Math.round(totalCost*100)/100, cigsPerDay:cigsPerDay, pricePerPack:pricePerPack,
    timeYearHours:Math.round(timeYearMin/60), note:'若今天戒烟，未来每年可省上述金额与约 '+Math.round(timeYearMin/60)+' 小时'};
}
var EXPORTS={quitSmoking:quitSmoking};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.QuitSmokingForgePure = EXPORTS; }
